13	declare_rule! {
14	    /// Disallow focused tests.
15	    ///
16	    /// Disabled test are useful when developing and debugging, because it forces the test suite to run only certain tests.
17	    ///
18	    /// However, in pull/merge request, you usually want to run all the test suite.
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```js,expect_diagnostic
25	    /// describe.only("foo", () => {});
26	    /// ```
27	    ///
28	    /// ```js,expect_diagnostic
29	    /// test.only("foo", () => {});
30	    /// ```
31	    ///
32	    /// ### Valid
33	    /// ```js
34	    /// test("foo", () => {});
35	    /// ```
36	    pub NoFocusedTests {
37	        version: "next",
38	        name: "noFocusedTests",
39	        recommended: true,
40	        source: RuleSource::EslintJest("no-focused-tests"),
41	        source_kind: RuleSourceKind::Inspired,
42	        fix_kind: FixKind::Unsafe,
43	    }
44	}
