48	impl Rule for NoFocusedTests {
49	    type Query = Ast<JsCallExpression>;
50	    type State = TextRange;
51	    type Signals = Option<Self::State>;
52	    type Options = ();
53	
54	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
55	        let node = ctx.query();
56	
57	        if node.is_test_call_expression().ok()? {
58	            let callee = node.callee().ok()?;
59	            if callee.contains_a_test_pattern().ok()? {
60	                let function_name = get_function_name(&callee)?;
61	
62	                if FUNCTION_NAMES.contains(&function_name.text_trimmed()) {
63	                    return Some(function_name.text_trimmed_range());
64	                }
65	            }
66	        }
67	
68	        None
69	    }
70	
71	    fn diagnostic(_: &RuleContext<Self>, range: &Self::State) -> Option<RuleDiagnostic> {
72	        Some(
73	            RuleDiagnostic::new(
74	                rule_category!(),
75	                range,
76	                markup! {
77	                    "Don't focus the test."
78	                },
79	            )
80	                .note("This is likely a change done during debugging or implementation phases, but it's unlikely what you want in production.")
81	                .note("Remove it.")
82	        )
83	    }
84	
85	    fn action(ctx: &RuleContext<Self>, _: &Self::State) -> Option<JsRuleAction> {
86	        let node = ctx.query();
87	        let callee = node.callee().ok()?;
88	        let function_name = get_function_name(&callee)?;
89	        let replaced_function;
90	
91	        let mut mutation = ctx.root().begin();
92	
93	        match function_name.text_trimmed() {
94	            "only" => {
95	                let member = callee.as_js_static_member_expression()?;
96	                let member_name = member.member().ok()?;
97	                let operator_token = member.operator_token().ok()?;
98	                // let member = member.as_js_name()?;
99	                mutation.remove_element(member_name.into());
100	                mutation.remove_element(operator_token.into());
101	            }
102	            "fit" => {
103	                replaced_function = make::js_reference_identifier(make::ident("it"));
104	                mutation.replace_element(function_name.into(), replaced_function.into());
105	            }
106	            "fdescribe" => {
107	                replaced_function = make::js_reference_identifier(make::ident("describe"));
108	                mutation.replace_element(function_name.into(), replaced_function.into());
109	            }
110	            _ => {}
111	        };
112	
113	        Some(JsRuleAction {
114	            category: biome_analyze::ActionCategory::QuickFix,
115	            applicability: Applicability::MaybeIncorrect,
116	            message: markup! { "Remove focus from test." }.to_owned(),
117	            mutation,
118	        })
119	    }
120	}
121	
122	fn get_function_name(callee: &AnyJsExpression) -> Option<JsSyntaxToken> {
123	    match callee {
124	        AnyJsExpression::JsStaticMemberExpression(node) => {
125	            let member = node.member().ok()?;
126	            let member = member.as_js_name()?;
127	            member.value_token().ok()
128	        }
129	        AnyJsExpression::JsIdentifierExpression(node) => node.name().ok()?.value_token().ok(),
130	        _ => None,
131	    }
132	}
